/* 怪物属性：凡界 / 秘境 / 仙冥魔神地图（含天将、星君、界主）/ 灵地 / 宗门考官 / 试炼塔。代码：data/mobs.js、modules/world.js、xingjun.js、sect.js
 * 每个怪物 4 个数：[境界, 层, 宗门组, 倍率]（坊市、功德司功法不算）
 *   境界 / 层：算属性用的境界序号和层（1~10，[1, 4] = 每次遇到随机 1~4 层）
 *   末尾可加额外倍率（写在下一行）：{ 生命, 攻击, 防御, jin 金抗, mu 木抗, shui 水抗, huo 火抗, tu 土抗, lei 雷抗 }，在倍率之后再乘，不写 = 1
 *     四界地图默认 生命 1.2；抗性每个怪物随机一系 1.26~1.45、两系 1.05~1.25，其余三系 1；按地图等级（10~29 级）从低到高线性增加，另有少量随机（六系各当高 140 次、中 280 次）
 *   每组 [类别, 前星学%, [前星层], 星级, 本星学%, [本星层]]，类别 1 宗门功法殿（不含传承）
 *     例 [1, 50, [3, 4], 2, 12, [1, 2]]：宗门 1 星功法学 50%、每本随机 3~4 层；2 星学 12%、每本随机 1~2 层
 *     前星 = 1 ~ 星级−1 的全部星级共用；学% = 每种功法学该段全部功法的 %（每星每种 12 本）；学% 或层写 0 = 这段不学
 *     学% 和层都可以写一个数或 [a, b]（遇到时随机：学% 每种一次，层每本一次）
 * 进入境界写在每组开头：进入（地图 / 秘境）；四界同一界每张图进入境界相同；灵地不限境界；天将、星君打赢就能就任（不限境界）
 * 属性 = (修为突破 GAIN + 同层数肉身突破 BODY_GAIN（config/realm.js）+ 功法) × 倍率，遇到时每项再 × 随机(RAND)；暴击% = CRIT（不乘倍率、不浮动）
 * 境界序号：0 练气 1 筑基 2 金丹 3 元婴 4 出窍 5 化神 6 练虚 7 合体 8 洞真 9 大乘 10 渡劫 11 散仙 12 游仙 13 地仙 14 天仙
 *   15 金仙 16 太乙金仙 17 大罗金仙 18 玄仙 19 仙王 20 仙君 21 仙帝 22 准圣 23 圣人 */
